from collections import defaultdict


def rrf(*rankings, k=60):
    """Reciprocal Rank Fusion: each list adds 1 / (k + rank)."""
    scores = defaultdict(float)
    for ranking in rankings:
        for rank, doc_id in enumerate(ranking, start=1):
            scores[doc_id] += 1 / (k + rank)
    return sorted(scores, key=scores.get, reverse=True)


def retrieve(query, k=20, pool=150):
    fused = rrf(vector_search(query, k=pool), keyword_search(query, k=pool))
    # A cross-encoder reads the query and each candidate together
    return rerank(query, fused[:pool])[:k]


